package ir.hamed.klox;
import android.app.*;import android.content.*;import android.os.Build;import java.util.*;
public final class ScheduleManager{private static final int REQUEST=4701;private static final int SLOTS=7;private ScheduleManager(){}
public static void scheduleNext(Context context){Context c=context.getApplicationContext();SharedPreferences p=c.getSharedPreferences("settings",Context.MODE_PRIVATE);cancel(c);if(!p.getBoolean("enabled",true))return;long next=nextAnnouncement(p,System.currentTimeMillis());if(next<0)return;AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(am==null)return;Intent i=new Intent(c,ScheduleReceiver.class).setAction(ScheduleReceiver.ACTION_ANNOUNCE);PendingIntent pi=PendingIntent.getBroadcast(c,REQUEST,i,PendingIntent.FLAG_UPDATE_CURRENT|immutable());if(Build.VERSION.SDK_INT>=31&&am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,pi);else if(Build.VERSION.SDK_INT>=23)am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,pi);else am.set(AlarmManager.RTC_WAKEUP,next,pi);}
private static int immutable(){return Build.VERSION.SDK_INT>=23?PendingIntent.FLAG_IMMUTABLE:0;}
public static void cancel(Context context){AlarmManager am=(AlarmManager)context.getApplicationContext().getSystemService(Context.ALARM_SERVICE);if(am==null)return;Intent i=new Intent(context,ScheduleReceiver.class).setAction(ScheduleReceiver.ACTION_ANNOUNCE);PendingIntent pi=PendingIntent.getBroadcast(context,REQUEST,i,PendingIntent.FLAG_UPDATE_CURRENT|immutable());am.cancel(pi);}
private static long nextAnnouncement(SharedPreferences p,long nowMs){Calendar c=Calendar.getInstance();c.setTimeInMillis(nowMs);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);c.add(Calendar.MINUTE,1);for(int i=0;i<2880;i++,c.add(Calendar.MINUTE,1)){int candidate=c.get(Calendar.HOUR_OF_DAY)*60+c.get(Calendar.MINUTE);for(int s=0;s<SLOTS;s++){if(!p.getBoolean("slot"+s+"Enabled",s==0))continue;int start=p.getInt("slot"+s+"Start",s==0?420:0);int end=p.getInt("slot"+s+"End",s==0?600:60);int interval=Math.max(1,p.getInt("slot"+s+"Interval",60));int endAbs=end<=start?end+1440:end;int cur=candidate;if(endAbs>1439&&candidate<start)cur+=1440;if(cur>=start&&cur<=endAbs&&(cur-start)%interval==0)return c.getTimeInMillis();}}return -1;}}
